sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    //MSSTRESURY-192:Implementation - Task Lock/Unlock with SWB Integration
    var user_id = request.body.data.user_id;
    var queue_name = request.body.data.queue_name;
    var task_sys_id = request.body.data.task_sys_id;
    var instruction_case_id = request.body.data.instruction_case_id;
    try {
        var authDetails = new x_hsb11_mss_tsd.MSS_Treasury_Utils().getUserAuthDetail(user_id, queue_name, task_sys_id, instruction_case_id);
        if (authDetails) {// MSSTRESURY-316: Removed if-else blocks and added below code
            response.setStatus(200);
            response.setBody(authDetails);
        } else {
            response.setStatus(500);
            response.setBody({
                error: 'Internal Server Error'
            });
        }
    } catch (e) {
        gs.error("Error in REST API (SWB AuthZ API swb_ui_verify_treasury_user) processing: " + e.message);
        response.setStatus(500);
        response.setBody({
            error: 'Internal Server Error'
        });
    }
})(request, response);
